import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.CDU0sSpB.js";const m=JSON.parse('{"title":"Documentation Map","description":"Hearth documentation structure, recommended reading order, maintenance rules, and release boundary.","frontmatter":{"title":"Documentation Map","description":"Hearth documentation structure, recommended reading order, maintenance rules, and release boundary.","outline":[2]},"headers":[],"relativePath":"en/reference/source-map.md","filePath":"en/reference/source-map.md","lastUpdated":1793890227000}'),o={name:"en/reference/source-map.md"};function i(d,e,s,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="documentation-map" tabindex="-1">Documentation Map <a class="header-anchor" href="#documentation-map" aria-label="Permalink to &quot;Documentation Map&quot;">​</a></h1><p class="lead">All formal documentation lives under `docs/`, and the repository and published site use the same content. Chinese is the default path; English uses the same structure. When you cannot find a kind of information, start here to decide which section to read.</p><h2 id="site-structure" tabindex="-1">Site structure <a class="header-anchor" href="#site-structure" aria-label="Permalink to &quot;Site structure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Content</th><th>Entry</th></tr></thead><tbody><tr><td>Get started</td><td>Local run, model connection, data and backup, development and tests</td><td><a href="/hearth-os/en/guide/">Quick start</a></td></tr><tr><td>Design</td><td>One overall design and eleven module notes explaining why the system is shaped this way</td><td><a href="/hearth-os/en/design/">Overall design</a></td></tr><tr><td>Delivery</td><td>Phase-one acceptance, phase 2–6 capabilities, remaining roadmap, acceptance rules</td><td><a href="/hearth-os/en/delivery/">Delivery overview</a></td></tr><tr><td>Development log</td><td>Day01–Day04 entries with commits, diffstats, and boundaries</td><td><a href="/hearth-os/en/log/">Development log</a></td></tr><tr><td>Reference</td><td>Engineering, risk, decisions, build boundaries, terminology, checklists, and maintenance</td><td><a href="/hearth-os/en/reference/">Reference</a></td></tr><tr><td>Site entry</td><td>Home page and language switch</td><td><a href="/hearth-os/en/">Home</a></td></tr></tbody></table><p>The design section is organised by capability, not by code directory: entrances and experience, tasks and durable execution, control and authority, executors and routing, native agent runtime, approvals and external effects, runtime and safety, memory and capability evolution, evaluation and cost, multi-device and long-running operation, plus agent reference patterns. They are peers and can be read in any order.</p><h2 id="recommended-reading-order" tabindex="-1">Recommended reading order <a class="header-anchor" href="#recommended-reading-order" aria-label="Permalink to &quot;Recommended reading order&quot;">​</a></h2><p>For a first read, follow &quot;why&quot;, then &quot;what exists now&quot;, then &quot;what is missing&quot;, then &quot;how to run it&quot;:</p><ol><li>Read the <a href="/hearth-os/en/design/">overall design</a> for positioning, task path, technology choices, and module boundaries;</li><li>Read the <a href="/hearth-os/en/delivery/">delivery overview</a> for the six phases, then enter <a href="/hearth-os/en/delivery/mvp.html">Phase-one acceptance</a> or <a href="/hearth-os/en/delivery/capabilities.html">Phase 2–6 capabilities</a> as needed;</li><li>To run it yourself, start with <a href="/hearth-os/en/guide/">Quick start</a>; to connect a model, read <a href="/hearth-os/en/guide/models.html">Connect a model</a>;</li><li>To continue development, read the <a href="/hearth-os/en/delivery/roadmap.html">remaining roadmap</a>, <a href="/hearth-os/en/delivery/acceptance.html">Acceptance and evidence</a>, and <a href="/hearth-os/en/reference/engineering.html">Engineering</a>.</li></ol><p>To decide quickly whether the project is worth more time, read the positioning section in the overall design and the status table in the delivery overview.</p><h2 id="maintenance-and-release-rules" tabindex="-1">Maintenance and release rules <a class="header-anchor" href="#maintenance-and-release-rules" aria-label="Permalink to &quot;Maintenance and release rules&quot;">​</a></h2><ol><li>Change Chinese first and confirm conclusions, boundaries, and links; update the English mirror in the same commit.</li><li>After changing structure, navigation, or the delivery route, check the reference area, sidebar, home page, language switch, and old links.</li><li>Do not introduce code paths, internal class names, or implementation examples into design pages; put engineering constraints in the reference area.</li><li>Delete old pages directly; do not keep redirects or duplicate body text. Search the site for old paths and remove dead links.</li><li>Run <code>npm run docs:build</code>, then check internal links, mobile width, dark mode, and search entries.</li><li>Do not use &quot;should&quot; or &quot;later&quot; to hide an undecided question. Mark unverified content as a hypothesis or leave it open.</li></ol><p>The documentation describes implemented code closures, acceptance evidence already collected, and boundaries still unaccepted. Phases 2–6 have runnable code and automated tests, but no real accounts, real devices, or long-running operation are presented as complete. Development logs record daily work and commits, not release notes. Maintain a formal version number and release notes only after an installable version exists.</p><p>The published site should match the build from <code>docs/</code>. After every deployment, verify that old addresses are gone, every bilingual page resolves, and the sidebar and home entries point to the new structure.</p>',13)])])}const p=t(o,[["render",i]]);export{m as __pageData,p as default};
